10	/// Find the start position of the current line in source text.
11	///
12	/// Given a slice of text, finds the byte offset where the current line begins
13	/// (after the last newline, handling CRLF).
14	pub(crate) fn find_line_start(before: &str) -> usize {
15	    let last_newline_pos = before.rfind(['\n', '\r']);
16	    match last_newline_pos {
17	        Some(pos) => {
18	            let bytes = before.as_bytes();
19	            // Handle CRLF: if we found \r and next char is \n, skip both
20	            if bytes.get(pos) == Some(&b'\r') && bytes.get(pos + 1) == Some(&b'\n') {
21	                pos + 2
22	            } else {
23	                pos + 1
24	            }
25	        }
26	        None => 0,
27	    }
28	}
