/// a backtick character, return the [`TextRange`] of the first such stray
/// backtick.
///
/// Per CommonMark §4.5, backtick fences cannot have backticks in their info
/// string; such a line is parsed as a paragraph rather than a code block.
/// Tilde fences allow backticks in their info string and always return `None`,
/// as does any line that does not open a fence.
pub(crate) fn backtick_fence_info_stray_backtick(p: &mut MarkdownParser) -> Option<TextRange> {
    p.lookahead(|p| {
        if !p.at_start_of_input() && !is_line_start_within_indent(p, MAX_BLOCK_PREFIX_INDENT) {
            return None;
        }
        p.skip_line_indent(MAX_BLOCK_PREFIX_INDENT);

        let fence_start: usize = p.cur_range().start().into();
        let rest = p.source_after_current();
        let (fence_char, fence_len) = detect_fence(rest)?;
        if fence_char != '`' {
            return None;
        }

        // The info string runs from the end of the fence to the end of the
        // line. Fence characters are ASCII backticks, so `fence_len` is also a
        // byte offset into `rest`.
        let info = rest[fence_len..]
            .split_terminator(['\n', '\r'])
            .next()
            .unwrap_or("");
        let backtick_offset = info.find('`')?;

        let start = fence_start + fence_len + backtick_offset;
        Some(TextRange::new(
            TextSize::from(start as u32),
            TextSize::from((start + 1) as u32),
        ))
    })
}

