643	pub(crate) fn parse_paragraph(p: &mut MarkdownParser) -> ParsedSyntax {
644	    let m = p.start();
645	
646	    let inline_start: usize = p.cur_range().start().into();
647	    parse_inline_item_list(p);
648	    let inline_end: usize = p.cur_range().start().into();
649	
650	    let has_inline_content = inline_has_non_whitespace(p, inline_start, inline_end);
651	    let allow_setext = has_inline_content && allow_setext_heading(p);
652	
653	    // Check if this paragraph is followed by a setext heading underline
654	    // MD_SETEXT_UNDERLINE_LITERAL is for `=` underlines
655	    // MD_THEMATIC_BREAK_LITERAL with only `-` is also a setext underline (H2)
656	    let completed = if allow_setext && p.at(MD_SETEXT_UNDERLINE_LITERAL) {
657	        let indent = real_line_indent_from_source(p);
658	        if indent < INDENT_CODE_BLOCK_SPACES {
659	            // This is a setext heading (H1 with `=`) - consume the underline
660	            p.bump(MD_SETEXT_UNDERLINE_LITERAL);
661	            m.complete(p, MD_SETEXT_HEADER)
662	        } else {
663	            // 4+ spaces of indent: not a setext underline (CommonMark §4.3)
664	            m.complete(p, MD_PARAGRAPH)
665	        }
666	    } else if allow_setext && p.at(MD_THEMATIC_BREAK_LITERAL) && is_dash_only_thematic_break(p) {
667	        let indent = real_line_indent_from_source(p);
668	        if indent < INDENT_CODE_BLOCK_SPACES {
669	            // This is a setext heading (H2 with `-`) - remap token and consume
670	            p.bump_remap(MD_SETEXT_UNDERLINE_LITERAL);
671	            m.complete(p, MD_SETEXT_HEADER)
672	        } else {
673	            // 4+ spaces of indent: not a setext underline (CommonMark §4.3)
674	            m.complete(p, MD_PARAGRAPH)
675	        }
676	    } else {
677	        m.complete(p, MD_PARAGRAPH)
678	    };
679	    Present(completed)
680	}
